    faces=c.V(g,sizes.outputs['Face Count'])
    islands=g.node('GeometryNodeInputMeshIsland','One welded transition surface')
    edge_uses=g.node('GeometryNodeInputMeshEdgeNeighbors','No loose or branched seam edges')
    vertex_uses=g.node('GeometryNodeInputMeshVertexNeighbors','No pinched or loose vertices')
    edge_faces=c.V(g,edge_uses.outputs['Face Count'])
    vertex_faces=c.V(g,vertex_uses.outputs['Face Count'])
    boundary_degree=c.V(g,vertex_uses.outputs['Vertex Count'])-vertex_faces
