    valid*=g.math('COMPARE',c._stat(g,geometry,islands.outputs['Island Count'],'Max'),1.)
    valid*=c._stat(g,geometry,g.math('GREATER_THAN',edge_faces,.5)*g.math('LESS_THAN',edge_faces,2.5),domain='EDGE')
    valid*=c._stat(g,geometry,g.math('GREATER_THAN',vertex_faces,.5)*
        g.math('GREATER_THAN',boundary_degree,-.5)*g.math('LESS_THAN',boundary_degree,1.5))
    return valid


